import sqlite3
from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

from .service import RegistrationError, RegistrationService
from .storage import Store


class EventInput(BaseModel):
    title: str = Field(min_length=1, max_length=80)
    capacity: int = Field(ge=1, le=1000)


class SignupInput(BaseModel):
    event_id: int = Field(ge=1)
    student_code: str = Field(min_length=3, max_length=32)


def create_app(database_path: Path):
    store = Store(database_path)
    store.initialize()
    service = RegistrationService(store)
    app = FastAPI(title="Campus Signup")

    @app.exception_handler(RegistrationError)
    async def registration_error(_request: Request, error: RegistrationError):
        return JSONResponse(status_code=error.status_code, content={"detail": str(error)})

    @app.exception_handler(sqlite3.DatabaseError)
    async def database_error(_request: Request, _error: sqlite3.DatabaseError):
        return JSONResponse(status_code=503, content={"detail": "Storage unavailable"})

    @app.post("/events", status_code=201)
    def create_event(payload: EventInput):
        return service.create_event(payload.title, payload.capacity)

    @app.get("/events")
    def list_events():
        return store.list_events()

    @app.post("/registrations", status_code=201)
    def register(payload: SignupInput):
        return service.register(payload.event_id, payload.student_code)

    @app.get("/registrations")
    def list_registrations():
        return store.list_registrations()

    @app.post("/registrations/{registration_id}/cancel")
    def cancel(registration_id: int):
        return service.cancel(registration_id)

    return app

PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    capacity INTEGER NOT NULL CHECK(capacity > 0),
    remaining INTEGER NOT NULL CHECK(remaining >= 0 AND remaining <= capacity)
);
CREATE TABLE IF NOT EXISTS registrations (
    id INTEGER PRIMARY KEY,
    event_id INTEGER NOT NULL REFERENCES events(id),
    student_code TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('active', 'cancelled')),
    UNIQUE(event_id, student_code)
);
CREATE TABLE IF NOT EXISTS audit_log (
    id INTEGER PRIMARY KEY,
    registration_id INTEGER NOT NULL REFERENCES registrations(id),
    action TEXT NOT NULL CHECK(action IN ('register', 'cancel'))
);

from .storage import Store


class RegistrationError(Exception):
    def __init__(self, message: str, status_code: int):
        super().__init__(message)
        self.status_code = status_code


class RegistrationService:
    def __init__(self, store: Store):
        self.store = store

    def create_event(self, title: str, capacity: int):
        if not title.strip() or capacity < 1:
            raise RegistrationError("Invalid event", 422)
        with self.store.transaction() as connection:
            cursor = connection.execute(
                "INSERT INTO events(title, capacity, remaining) VALUES (?, ?, ?)",
                (title.strip(), capacity, capacity),
            )
            return {"id": cursor.lastrowid, "title": title.strip(),
                    "capacity": capacity, "remaining": capacity}

    def register(self, event_id: int, student_code: str):
        with self.store.transaction() as connection:
            event = connection.execute(
                "SELECT id, remaining FROM events WHERE id = ?", (event_id,)
            ).fetchone()
            if event is None:
                raise RegistrationError("Event not found", 404)
            previous = connection.execute(
                "SELECT id FROM registrations WHERE event_id = ? AND student_code = ?",
                (event_id, student_code),
            ).fetchone()
            if previous is not None:
                raise RegistrationError("Registration already exists", 409)
            updated = connection.execute(
                "UPDATE events SET remaining = remaining - 1 WHERE id = ? AND remaining > 0",
                (event_id,),
            )
            if updated.rowcount != 1:
                raise RegistrationError("Event full", 409)
            cursor = connection.execute(
                "INSERT INTO registrations(event_id, student_code, status) VALUES (?, ?, 'active')",
                (event_id, student_code),
            )
            registration_id = cursor.lastrowid
            connection.execute(
                "INSERT INTO audit_log(registration_id, action) VALUES (?, 'register')",
                (registration_id,),
            )
            return {"id": registration_id, "event_id": event_id,
                    "student_code": student_code, "status": "active"}

    def cancel(self, registration_id: int):
        with self.store.transaction() as connection:
            row = connection.execute(
                "SELECT event_id, student_code, status FROM registrations WHERE id = ?",
                (registration_id,),
            ).fetchone()
            if row is None:
                raise RegistrationError("Registration not found", 404)
            if row["status"] != "active":
                raise RegistrationError("Registration already cancelled", 409)
            connection.execute(
                "UPDATE registrations SET status = 'cancelled' WHERE id = ?", (registration_id,)
            )
            connection.execute(
                "UPDATE events SET remaining = remaining + 1 WHERE id = ?", (row["event_id"],)
            )
            connection.execute(
                "INSERT INTO audit_log(registration_id, action) VALUES (?, 'cancel')",
                (registration_id,),
            )
            return {"id": registration_id, "event_id": row["event_id"],
                    "student_code": row["student_code"], "status": "cancelled"}

import sqlite3
from contextlib import closing, contextmanager
from pathlib import Path


class Store:
    def __init__(self, path: Path):
        self.path = path

    def connect(self):
        connection = sqlite3.connect(self.path, timeout=5, isolation_level=None)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys = ON")
        return connection

    def initialize(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with closing(self.connect()) as connection:
            connection.executescript(Path(__file__).with_name("schema.sql").read_text())

    @contextmanager
    def transaction(self):
        with closing(self.connect()) as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                yield connection
                connection.commit()
            except Exception:
                connection.rollback()
                raise

    def list_events(self):
        with closing(self.connect()) as connection:
            return [dict(row) for row in connection.execute(
                "SELECT id, title, capacity, remaining FROM events ORDER BY id"
            )]

    def list_registrations(self):
        with closing(self.connect()) as connection:
            return [dict(row) for row in connection.execute(
                "SELECT id, event_id, student_code, status FROM registrations ORDER BY id"
            )]
